<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { api,errorText,hasRole } from '../api'
import { useLoad,time,shortId } from '../composables'
import type { Page,Definition } from '../types'
import StatusBadge from './StatusBadge.vue'
import PageState from './PageState.vue'
import PaginationBar from './PaginationBar.vue'
import CheckEditor from './CheckEditor.vue'
import AppIcon from './AppIcon.vue'
const props=defineProps<{targetId:string}>(),page=ref(0),editor=ref<Definition|null|undefined>(undefined),stateAction=ref<{definition:Definition;state:string}|null>(null),reason=ref(''),busy=ref(false),saveError=ref('')
const {data,loading,error,load}=useLoad(()=>api<Page<Definition>>(`/targets/${props.targetId}/checks?page=${page.value}&size=20`))
onMounted(load)
function edit(d:Definition|null){stateAction.value=null;editor.value=d;saveError.value=''}
function selectState(d:Definition,state:string){editor.value=undefined;stateAction.value={definition:d,state};reason.value='';saveError.value=''}
async function setState(){if(!stateAction.value)return;busy.value=true;saveError.value='';const {definition:d,state}=stateAction.value;try{await api(`/targets/${props.targetId}/checks/${d.id}/state`,{method:'PUT',body:{configVersion:d.configVersion,state,reason:reason.value}});stateAction.value=null;await load()}catch(e){saveError.value=errorText(e)}finally{busy.value=false}}
function refresh(){editor.value=undefined;stateAction.value=null;saveError.value='' ;void load()}
function saved(){editor.value=undefined;void load()}
</script>
<template><div class="panel-heading"><div><h2>健康检查</h2><p>按阈值聚合故障；同一目标的探测间隔至少 60 秒。</p></div><div class="actions"><button class="btn" :disabled="loading||busy" @click="refresh">刷新检查</button><button v-if="hasRole('OPS_ADMIN')" class="btn primary" @click="edit(null)"><AppIcon name="plus" :size="16" />新增检查</button></div></div><CheckEditor v-if="editor!==undefined" :key="editor?.id||'new'" :target-id="targetId" :definition="editor||undefined" @done="saved" @refresh="refresh" @cancel="editor=undefined" /><form v-if="stateAction" class="inline-form" @submit.prevent="setState"><h3>变更检查状态 · {{ shortId(stateAction.definition.id) }}</h3><p>将状态设为 <StatusBadge :value="stateAction.state" />。暂停会中断当前恢复观察。</p><div v-if="saveError" class="error-message" role="alert">{{ saveError }}<button type="button" class="text-button" @click="refresh">放弃编辑并刷新</button></div><label>操作理由<input v-model="reason" required maxlength="500" placeholder="说明启用、暂停或禁用的原因"></label><div class="form-actions"><button type="button" class="btn" :disabled="busy" @click="stateAction=null">取消</button><button class="btn primary" :disabled="busy">{{ busy?'保存中…':'确认变更' }}</button></div></form><PageState :loading="loading&&!data" :error="error" :empty="!!data&&!data.items.length" title="尚未配置检查" description="配置请求方法、间隔和阈值，然后启用检查以开始监控。" @retry="load"><template v-if="data"><div class="table-scroll"><table><thead><tr><th>检查</th><th>状态</th><th>间隔 / 超时</th><th>预期状态码</th><th>失败 / 成功</th><th>下次计划</th><th v-if="hasRole('OPS_ADMIN')">操作</th></tr></thead><tbody><tr v-for="d in data.items" :key="d.id"><td><strong>{{ d.method }}</strong><small class="cell-note mono" :title="d.id">{{ shortId(d.id) }} · v{{ d.configVersion }}</small></td><td><StatusBadge :value="d.state" /></td><td class="mono">{{ d.intervalSeconds }} s / {{ d.timeoutMs }} ms</td><td class="mono">{{ d.expectedStatuses.join(', ') }}</td><td class="mono">{{ d.failureCount }}/{{ d.failThreshold }} · {{ d.successCount }}/{{ d.recoverThreshold }}</td><td class="timestamp">{{ d.state==='ACTIVE'?time(d.nextRunAt):'—' }}</td><td v-if="hasRole('OPS_ADMIN')"><div class="row-actions"><button class="text-button" @click="edit(d)">编辑</button><button class="text-button" @click="selectState(d,d.state==='ACTIVE'?'PAUSED':'ACTIVE')">{{ d.state==='ACTIVE'?'暂停':d.state==='PAUSED'?'恢复':'启用' }}</button><button v-if="d.state!=='DISABLED'" class="text-button muted" @click="selectState(d,'DISABLED')">禁用</button></div></td></tr></tbody></table></div><PaginationBar :page="page" :size="20" :total="data.total" :loading="loading" @change="p=>{page=p;load()}" /></template></PageState></template>
